using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>  → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 38), personInfo);
Console.WriteLine($"  Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// 2a. Type that IS resolvable (web defaults use the reflection resolver)
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
    Console.WriteLine($"TryGetTypeInfo<Person>  → resolved ({found!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<Person>  → not available");

// 2b. Type that is NOT resolvable (empty resolver → nothing is known)
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()  // knows all types
};
// Compose with an empty resolver that knows nothing
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine()     // resolves nothing
};

if (empty.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? missing))
    Console.WriteLine($"TryGetTypeInfo<Person> (empty) → resolved ({missing!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<Person> (empty) → not available  (no exception thrown!)");

// --- done ---
public record Person(string Name, int Age);

